1	package ports
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"math"
8		"os"
9		"strconv"
10		"testing"
11		"time"
12	)
13	
14	// Identity tells one process from a later one that got the same PID
15	// (DEVDESK-709). It is the creation stamp in the operating system's own unit,
16	// read once per PID when the table is listed. It is opaque: the interface only
17	// asks Verifiable, and this package compares. The zero value is "unknown", which
18	// Kill refuses, so a caller that forgets the identity cannot send a signal.
19	type Identity struct {
20		kind identityKind
21		raw  uint64
22	}
23	
24	type identityKind uint8
25	
26	const (
27		// identityNone is the zero value: not read, or unreadable.
28		identityNone identityKind = iota
29		// identityKnown carries the creation stamp, in the unit of the OS.
30		identityKnown
31		// identityDeferred is Windows only: the listing stopped reading because its
32		// budget ran out. raw is the listing instant (Unix ns); the stamp is read
33		// when the confirmation opens (ConfirmIdentity).
34		identityDeferred
35	)
36	
37	// The Windows budget and slack (S-01b criterion 7, hypothesis H1).
38	const (
39		// windowsIdentityBudget caps what reading identities adds to one refresh on
40		// Windows. Past it the remaining PIDs are deferred. The starting value of the
41		// story: adjust it from docs/measurements.
42		windowsIdentityBudget = 100 * time.Millisecond
43		// windowsBirthSlack is the granularity allowed between a creation time and the
44		// listing instant before a process counts as born before the listing.
45		windowsBirthSlack = 100 * time.Millisecond
46	)
47	
48	// Verifiable reports whether a stop can still be attempted for the row: the
49	// identity is known, or deferred and read when the confirmation opens.
50	func (i Identity) Verifiable() bool { return i.kind != identityNone }
51	
52	// Conflicts reports whether two identities say, with certainty, that they are
53	// two different processes: both known and different. An unknown or deferred one
54	// never conflicts.
55	func (i Identity) Conflicts(j Identity) bool {
56		return i.kind == identityKnown && j.kind == identityKnown && i.raw != j.raw
57	}
58	
59	// deferredAt is the identity of a PID not read at the listing taken at listedAt.
60	func deferredAt(listedAt time.Time) Identity {
61		return Identity{kind: identityDeferred, raw: uint64(listedAt.UnixNano())} //nolint:gosec // listing instants are after 1970
62	}
63	
64	// IdentityForTest builds a known identity for the fixtures of a test. It panics
65	// outside a test binary.
66	func IdentityForTest(raw uint64) Identity {
67		mustBeUnderTest("IdentityForTest")
68		return Identity{kind: identityKnown, raw: raw}
69	}
70	
71	// DeferredIdentityForTest builds a deferred identity, as a Windows listing does
72	// for a PID it did not read in time. It panics outside a test binary.
73	func DeferredIdentityForTest(listedAt time.Time) Identity {
74		mustBeUnderTest("DeferredIdentityForTest")
75		return deferredAt(listedAt)
76	}
77	
78	func mustBeUnderTest(name string) {
79		if !testing.Testing() {
80			panic("ports: " + name + " is reserved for tests (DEVDESK-709)")
81		}
82	}
83	
84	// UnverifiableError is the refusal when DevDesk cannot tell which process holds
85	// the PID. It is DevDesk's own decision, not the system's: it wraps no OS
86	// sentinel, so the interface cannot read it as "refused by the system".
87	type UnverifiableError struct {
88		PID   int
89		Cause error // for the log only; deliberately not returned by Unwrap
90	}
91	
92	func (e *UnverifiableError) Error() string {
93		return fmt.Sprintf("Cannot verify which process PID %d is — not stopped", e.PID)
94	}
95	
96	// IdentityChangedError is the refusal when the PID is held by another process
97	// than the one that was listed.
98	type IdentityChangedError struct{ PID int }
99	
100	func (e *IdentityChangedError) Error() string {
101		return fmt.Sprintf("PID %d is no longer the process that was listed — not stopped", e.PID)
102	}
103	
104	// parseStartTicks reads the starttime (field 22, ticks since boot) of a
105	// /proc/<pid>/stat line. The command name (field 2) sits between parentheses and
106	// may hold spaces and parentheses itself, so the fields are counted from the
107	// last ")".
108	func parseStartTicks(stat []byte) (uint64, error) {
109		end := bytes.LastIndexByte(stat, ')')
110		if end < 0 {
111			return 0, errors.New("no closing parenthesis in the stat line")
112		}
113		// Fields 3 onward follow the name: field 22 is the 20th of them.
114		const startIndex = 22 - 3
115		fields := bytes.Fields(stat[end+1:])
116		if len(fields) <= startIndex {
117			return 0, fmt.Errorf("the stat line stops at field %d, before starttime (22)", len(fields)+2)
118		}
119		ticks, err := strconv.ParseUint(string(fields[startIndex]), 10, 64)
120		if err != nil {
121			return 0, fmt.Errorf("reading starttime from the stat line: %w", err)
122		}
123		return ticks, nil
124	}
125	
126	// timevalStamp is a macOS process start (seconds and microseconds) as one value.
127	func timevalStamp(sec int64, usec int32) uint64 {
128		return uint64(sec)*1_000_000 + uint64(usec) //nolint:gosec // a start time is positive
129	}
130	
131	// unixAsFiletime is the Unix epoch as a Windows FILETIME (100 ns since 1601).
132	const unixAsFiletime = 116444736000000000
133	
134	// maxFiletimeTicks is the largest count of 100 ns ticks after the Unix epoch
135	// whose nanoseconds still fit in an int64.
136	const maxFiletimeTicks = math.MaxInt64 / 100
137	
138	// filetimeUnixNano turns a Windows FILETIME into Unix nanoseconds. A value
139	// before the Unix epoch or past what an int64 of nanoseconds holds is not a
140	// creation time DevDesk can compare: it comes back false, an unknown identity,
141	// rather than a wrapped-around instant.
142	func filetimeUnixNano(raw uint64) (int64, bool) {
143		if raw < unixAsFiletime {
144			return 0, false
145		}
146		ticks := raw - unixAsFiletime
147		if ticks > maxFiletimeTicks {
148			return 0, false
149		}
150		return int64(ticks) * 100, true //nolint:gosec // bounded by maxFiletimeTicks above
151	}
152	
153	// birth says where a Windows creation time falls against the listing instant.
154	type birth int
155	
156	const (
157		// bornBefore: the process existed at the listing, with the slack to spare.
158		bornBefore birth = iota
159		// bornAround: too close to the listing instant to tell.
160		bornAround
161		// bornAfter: the process did not exist at the listing.
162		bornAfter
163	)
164	
165	// judgeBirth places a creation time (Unix ns) against the listing instant
166	// (Unix ns). The slack absorbs the granularity of the creation time and of the
167	// clock.
168	func judgeBirth(createdNs, listedAtNs int64, slack time.Duration) birth {
169		switch {
170		case createdNs <= listedAtNs-int64(slack):
171			return bornBefore
172		case createdNs > listedAtNs:
173			return bornAfter
174		default:
175			return bornAround
176		}
177	}
178	
179	// verdictAtSignal is the decision realOS.kill applies to what it read with the
180	// process held: nil means send. A failed read never sends, whatever the stamp.
181	func verdictAtSignal(pid int, want Identity, got uint64, readErr error) error {
182		if readErr != nil {
183			if errors.Is(readErr, os.ErrProcessDone) {
184				return fmt.Errorf("process %d: %w", pid, os.ErrProcessDone)
185			}
186			return &UnverifiableError{PID: pid, Cause: readErr}
187		}
188		if want.kind != identityKnown {
189			return &UnverifiableError{PID: pid}
190		}
191		if got != want.raw {
192			return &IdentityChangedError{PID: pid}
193		}
194		return nil
195	}
196	
197	// ConfirmIdentity gives the identity a stop of the row must be verified
198	// against. A known identity comes back as it is, with no system call; a
199	// deferred one (Windows, over the listing budget) is read now and anchored to
200	// the listing instant; an unknown one is refused. The errors are those of Kill:
201	// an OS refusal or a gone process stays readable through errors.Is, DevDesk's
202	// own refusals are an *UnverifiableError and an *IdentityChangedError.
203	func ConfirmIdentity(pid string, listed Identity) (Identity, error) {
204		n, ok := parsePID(pid)
205		if !ok || n <= 0 {
206			return Identity{}, fmt.Errorf("not a process id: %q", pid)
207		}
208		switch listed.kind {
209		case identityKnown:
210			return listed, nil
211		case identityDeferred:
212			return confirmDeferred(n, listed)
213		default:
214			return Identity{}, &UnverifiableError{PID: n}
215		}
216	}
217	
218	// confirmDeferred reads the stamp of a PID the listing did not read, and keeps
219	// it only if the process was born before the listing.
220	func confirmDeferred(n int, listed Identity) (Identity, error) {
221		raw, err := procOS.identity(n)
222		if err != nil {
223			if errors.Is(err, os.ErrPermission) || errors.Is(err, os.ErrProcessDone) {
224				return Identity{}, fmt.Errorf("reading the identity of process %d: %w", n, err)
225			}
226			return Identity{}, &UnverifiableError{PID: n, Cause: err}
227		}
228		createdNs, ok := filetimeUnixNano(raw)
229		if !ok {
230			return Identity{}, &UnverifiableError{PID: n}
231		}
232		switch judgeBirth(createdNs, int64(listed.raw), windowsBirthSlack) { //nolint:gosec // a listing instant fits in int64
233		case bornBefore:
234			return Identity{kind: identityKnown, raw: raw}, nil
235		case bornAfter:
236			return Identity{}, &IdentityChangedError{PID: n}
237		default:
238			return Identity{}, &UnverifiableError{PID: n}
239		}
240	}
