1	package netdiag
2	
3	import (
4		"context"
5		"runtime"
6		"time"
7	
8		tea "charm.land/bubbletea/v2"
9	
10		"github.com/anthnel/devdesk/internal/ports"
11	)
12	
13	// NewPortsDataMsg hands socket rows to the Ports view without reading the real
14	// socket table (guard seed, DEVDESK-150 H8).
15	func NewPortsDataMsg(sockets []ports.Socket) tea.Msg { return portsDataMsg{ports: sockets} }
16	
17	// defaultPortsRefresh is what the interval falls back to. A non-positive one —
18	// a hand-edited 0 in the config — would make tea.Tick fire without pausing and
19	// spin a docker exec per frame, so it is refused here rather than trusted.
20	const defaultPortsRefresh = 2 * time.Second
21	
22	func portsTickCmd(every time.Duration) tea.Cmd {
23		if every <= 0 {
24			every = defaultPortsRefresh
25		}
26		return tea.Tick(every, func(time.Time) tea.Msg {
27			return portsTickMsg{}
28		})
29	}
30	
31	// portsFetchTimeout bounds one read. Reverse DNS is the part that can hang —
32	// the socket table itself is a system call — and a fetch outliving several
33	// ticks would stack one behind another.
34	const portsFetchTimeout = 5 * time.Second
35	
36	func fetchPortsCmd(numeric bool) tea.Cmd {
37		return func() tea.Msg {
38			ctx, cancel := context.WithTimeout(context.Background(), portsFetchTimeout)
39			defer cancel()
40			sockets, err := ports.List(ctx, !numeric)
41			return portsDataMsg{ports: sockets, err: err}
42		}
43	}
44	
45	// processOps is what the Ports tab does to the machine's processes, held in
46	// one value so a test can replace it and no test signals a real process.
47	type processOps struct {
48		// protection says whether DevDesk refuses to signal the process with this
49		// PID. It is read in Update and at render, never in a Cmd (Rule 110).
50		protection func(pid string) ports.Protection
51		// confirm settles which process a row is when its confirmation opens: it
52		// hands back the identity the signal will be verified against, or the reason
53		// DevDesk cannot tell. For a row listed with an identity it reads nothing;
54		// only a deferred one (Windows, over the listing budget) costs a system
55		// call, in Update and at the press of K (DEVDESK-709).
56		confirm func(pid string, listed ports.Identity) (ports.Identity, error)
57		// kill ends the process with this PID, provided it still is the process
58		// with the identity the row was listed with.
59		kill func(pid string, listed ports.Identity) error
60		// windows says the platform has no clean stop, which changes the wording
61		// of the confirmation and of the help, nothing else.
62		windows bool
63	}
64	
65	// realProcessOps is the production wiring: ports.Kill on the platform the
66	// binary runs on.
67	func realProcessOps() processOps {
68		return processOps{
69			protection: ports.ProtectionOf,
70			confirm:    ports.ConfirmIdentity,
71			kill:       ports.Kill,
72			windows:    runtime.GOOS == "windows",
73		}
74	}
75	
76	// killProcessCmd signals the target through kill. Both are values captured in
77	// Update (Rule 110): the command never reads the model.
78	func killProcessCmd(kill func(string, ports.Identity) error, t killTarget) tea.Cmd {
79		return func() tea.Msg {
80			return portsKillResultMsg{pid: t.PID, process: t.Process, err: kill(t.PID, t.Identity)}
81		}
82	}
83	
84	// portsRefreshMsg asks for one read of the socket table now, outside the tick
85	// chain: a second portsTickMsg would start a second chain (DEVDESK-709).
86	type portsRefreshMsg struct{}
87	
88	// requestPortsRefresh returns the command that delivers a portsRefreshMsg. It
89	// reads nothing itself; Update turns the message into the read.
90	func requestPortsRefresh() tea.Cmd {
91		return func() tea.Msg { return portsRefreshMsg{} }
92	}
93

